let cars=[
 {id:1,brand:'Toyota',name:'Corolla XEI',year:2023,km:'28.000 km',fuel:'Nafta',gear:'Automático',type:'Sedán',price:34500000,status:'Nuevo ingreso',image:'assets/toyota-corolla-xei.webp',color:'Gris grafito',engine:'2.0L · 170 CV'},
 {id:2,brand:'Volkswagen',name:'Taos Comfortline',year:2022,km:'41.500 km',fuel:'Nafta',gear:'Automático',type:'SUV',price:42900000,status:'Destacado',image:'assets/volkswagen-taos.webp',color:'Blanco',engine:'1.4 TSI · 150 CV'},
 {id:3,brand:'Chevrolet',name:'Tracker Premier',year:2024,km:'12.800 km',fuel:'Nafta',gear:'Automático',type:'SUV',price:39700000,status:'Oportunidad',image:'assets/chevrolet-tracker.webp',color:'Blanco perlado',engine:'1.2 Turbo · 132 CV'},
 {id:4,brand:'Ford',name:'Focus Titanium',year:2019,km:'67.000 km',fuel:'Nafta',gear:'Automático',type:'Hatchback',price:24800000,status:'Disponible',image:'assets/ford-focus.webp',color:'Azul profundo',engine:'2.0L · 170 CV'},
 {id:5,brand:'Volkswagen',name:'Golf Highline',year:2020,km:'53.400 km',fuel:'Nafta',gear:'Automático',type:'Hatchback',price:28600000,status:'Financiación',image:'assets/volkswagen-golf.webp',color:'Azul metálico',engine:'1.4 TSI · 150 CV'},
 {id:6,brand:'Toyota',name:'Corolla Cross XEI',year:2023,km:'31.200 km',fuel:'Híbrido',gear:'Automático',type:'SUV',price:46800000,status:'Próximo ingreso',image:'assets/toyota-corolla-cross.webp',color:'Blanco',engine:'1.8 Hybrid · 122 CV'}
];
const money=n=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:0}).format(n);
const grid=document.querySelector('#vehicleGrid'),count=document.querySelector('#resultCount'),empty=document.querySelector('#emptyState');
let activeFilter='all',favorites=new Set();
function filteredCars(){const brand=document.querySelector('#searchBrand').value,type=document.querySelector('#searchType').value,max=+document.querySelector('#searchPrice').value;return cars.filter(c=>(activeFilter==='all'||c.type===activeFilter)&&(brand==='all'||c.brand===brand)&&(type==='all'||c.type===type)&&c.price<=max)}
function render(){const list=filteredCars();count.textContent=`${list.length} vehículo${list.length===1?'':'s'}`;empty.hidden=!!list.length;grid.innerHTML=list.map(c=>`<article class="vehicle-card"><div class="vehicle-photo"><img src="${c.image}" alt="${c.brand} ${c.name}" loading="lazy"><span class="badge ${c.status==='Oportunidad'?'offer':''}">${c.status}</span><button class="heart ${favorites.has(c.id)?'active':''}" data-fav="${c.id}" aria-label="Guardar ${c.name}">${favorites.has(c.id)?'♥':'♡'}</button></div><div class="vehicle-body"><span class="vehicle-meta">${c.brand.toUpperCase()} · ${c.type.toUpperCase()}</span><h3>${c.name}</h3><div class="specs"><span>${c.year}</span><span>${c.km}</span><span>${c.gear}</span></div><div class="price-row"><div><small>Precio publicado</small><strong>${money(c.price)}</strong></div></div><div class="vehicle-actions"><button class="btn primary" data-detail="${c.id}">Ver vehículo</button></div></div></article>`).join('')}
document.querySelectorAll('.chip').forEach(b=>b.onclick=()=>{document.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));b.classList.add('active');activeFilter=b.dataset.filter;render()});
document.querySelector('#searchBtn').onclick=()=>{activeFilter='all';document.querySelectorAll('.chip').forEach((x,i)=>x.classList.toggle('active',i===0));render();document.querySelector('#stock').scrollIntoView()};
document.querySelector('#clearFilters').onclick=()=>{document.querySelector('#searchBrand').value='all';document.querySelector('#searchType').value='all';document.querySelector('#searchPrice').value='999999999';activeFilter='all';render()};
grid.onclick=e=>{const fav=e.target.closest('[data-fav]'),detail=e.target.closest('[data-detail]');if(fav){const id=+fav.dataset.fav;favorites.has(id)?favorites.delete(id):favorites.add(id);render();toast(favorites.has(id)?'Guardado en favoritos':'Eliminado de favoritos')}if(detail)openDetail(+detail.dataset.detail)};
function openDetail(id){const c=cars.find(x=>x.id===id),msg=encodeURIComponent(`Hola VZ Automotores, quiero consultar por el ${c.brand} ${c.name} ${c.year}. ¿Sigue disponible?`);document.querySelector('#vehicleDetail').innerHTML=`<div class="detail-grid"><img src="${c.image}" alt="${c.brand} ${c.name}"><div class="detail-copy"><span class="eyebrow">${c.status.toUpperCase()}</span><h2>${c.brand} ${c.name}</h2><div class="detail-price">${money(c.price)}</div><div class="detail-specs"><span><b>${c.year}</b>Año</span><span><b>${c.km}</b>Kilómetros</span><span><b>${c.engine}</b>Motor</span><span><b>${c.gear}</b>Transmisión</span><span><b>${c.fuel}</b>Combustible</span><span><b>${c.color}</b>Color</span></div><a class="btn primary full" target="_blank" rel="noopener" href="https://wa.me/5492475402499?text=${msg}">Consultar por WhatsApp</a><button class="btn glass full" style="margin-top:9px" onclick="document.querySelector('#vehicleDialog').close();document.querySelector('#financiacion').scrollIntoView()">Simular financiación</button></div></div>`;document.querySelector('#vehicleDialog').showModal()}
document.querySelectorAll('dialog').forEach(d=>d.querySelector('.dialog-close').onclick=()=>d.close());
const vehicleValue=document.querySelector('#vehicleValue'),deposit=document.querySelector('#deposit');let term=24;function calc(){const val=+vehicleValue.value,dep=Math.min(+deposit.value,val*.8);if(+deposit.value!==dep)deposit.value=dep;document.querySelector('#vehicleValueOut').value=money(val);document.querySelector('#depositOut').value=money(dep);const monthly=Math.round(((val-dep)*(1+term*.0125))/term);document.querySelector('#monthlyOut').textContent=money(monthly);const msg=encodeURIComponent(`Hola VZ Automotores, hice una simulación por un vehículo de ${money(val)}, con ${money(dep)} de anticipo y ${term} cuotas. Quiero recibir una propuesta.`);document.querySelector('#financeWhatsApp').href=`https://wa.me/5492475402499?text=${msg}`}
vehicleValue.oninput=calc;deposit.oninput=calc;document.querySelectorAll('[data-term]').forEach(b=>b.onclick=()=>{term=+b.dataset.term;document.querySelectorAll('[data-term]').forEach(x=>x.classList.toggle('active',x===b));calc()});calc();
document.querySelector('#tradeForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),payload={vehicle:fd.get('vehicle'),year:Number(fd.get('year')),km:Number(fd.get('km')),phone:fd.get('phone')},msg=encodeURIComponent(`Hola VZ Automotores, quiero tasar mi usado: ${payload.vehicle}, año ${payload.year}, ${payload.km} km. Mi teléfono es ${payload.phone}.`);document.querySelector('#tradeStatus').textContent='Guardando tu solicitud…';try{const response=await fetch('/api/trade-ins',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok)throw new Error();document.querySelector('#tradeStatus').textContent='¡Solicitud guardada! Te llevamos a WhatsApp para continuar.'}catch{document.querySelector('#tradeStatus').textContent='Continuamos por WhatsApp para completar la solicitud.'}setTimeout(()=>window.open(`https://wa.me/5492475402499?text=${msg}`,'_blank'),550)};
const toastEl=document.querySelector('#toast');function toast(t){toastEl.textContent=t;toastEl.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2200)}
const menu=document.querySelector('.menu-btn');menu.onclick=()=>{const nav=document.querySelector('nav'),open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',!open);nav.style.display=open?'none':'flex';nav.style.position='absolute';nav.style.top='70px';nav.style.left='0';nav.style.right='0';nav.style.padding='20px';nav.style.background='#090c10';nav.style.flexDirection='column'};
async function loadVehicles(){try{const response=await fetch('/api/vehicles');if(!response.ok)throw new Error();const data=await response.json();if(Array.isArray(data.vehicles)&&data.vehicles.length){cars=data.vehicles.map(c=>({...c,image:`assets/${c.image.replace(/\.png$/i,'.webp')}`}));render();}}catch{render();}}
render();loadVehicles();
